CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE TYPE app_role AS ENUM('owner','manager','cashier','waiter','founder');
CREATE TABLE restaurants(id uuid PRIMARY KEY,slug text,has_order boolean DEFAULT true);
CREATE TABLE user_roles(user_id uuid,restaurant_id uuid,role app_role,suspended boolean DEFAULT false);
CREATE FUNCTION has_restaurant_role(uuid,uuid,app_role[]) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=$1 AND restaurant_id=$2 AND NOT suspended AND (role=ANY($3) OR role='manager' AND 'cashier'=ANY($3))) $$;
CREATE TABLE restaurant_tables(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid,number text,active boolean,session_token text,waiter_id uuid);
CREATE TABLE pdv_waiters(id uuid PRIMARY KEY,user_id uuid,restaurant_id uuid,name text,active boolean);
CREATE TABLE pdv_menu_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid,code text,name text,price numeric,sector text,available boolean);
CREATE TABLE pdv_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid,table_number text,waiter_id uuid,created_by uuid,request_id text,UNIQUE(restaurant_id,request_id));
CREATE TABLE pdv_order_items(order_id uuid,restaurant_id uuid,item_code text,item_name text,unit_price numeric,quantity int,notes text,sector text);
CREATE TABLE table_bill_items(restaurant_slug text,table_number text,item_code text,item_name text,unit_price numeric,ordered_quantity int,ordered_by text,ordered_at timestamptz,source_adapter text,notes text,UNIQUE(restaurant_slug,table_number,item_code));
CREATE FUNCTION table_is_over_limit(uuid,text) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE FUNCTION restaurant_has_module(uuid,text) RETURNS boolean LANGUAGE sql AS $$ SELECT has_order FROM restaurants WHERE id=$1 $$;
CREATE FUNCTION open_table_ordering(text,text) RETURNS jsonb LANGUAGE plpgsql AS $$ BEGIN IF current_setting('test.fail_open',true)='yes' THEN RAISE EXCEPTION 'database unavailable'; END IF; RETURN '{"requires_code":false}'::jsonb; END $$;
CREATE FUNCTION pdv_close_table(text,text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN UPDATE restaurant_tables SET session_token='new-session' WHERE restaurant_id=(SELECT id FROM restaurants WHERE slug=$1) AND number=$2; END $$;
CREATE FUNCTION test_limit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF current_setting('test.table_limit',true)='yes' AND NEW.active AND NOT OLD.active THEN RETURN NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER test_limit BEFORE UPDATE ON restaurant_tables FOR EACH ROW EXECUTE FUNCTION test_limit();
